// Morning briefing: the prompt, and the shape saved to data/briefing.json.
// Generated by scripts/briefing.ts (GitHub Action, weekdays ~06:40 UK time).

export interface Briefing {
  /** ISO time it was written. */
  generatedAt: string;
  /** London date it is for (YYYY-MM-DD). */
  date: string;
  /** Short markdown: "## " headings, "- " bullets, **bold**. */
  markdown: string;
  sources: { title: string; url: string }[];
}

export const BRIEFING_SYSTEM = `You write a pre-market morning briefing for a UK-based professional investor who covers gilts and UK rates, global government bonds, equities, FX and commodities.

What to cover, for the UK, US and Europe (with Asia only as it affects them):
- Sovereign bonds, equities, FX and commodities: the moves that matter since the last close and why.
- Major macro and policy news: central banks, data surprises, fiscal news.
- Key political or geopolitical news only where it moves or could move markets.
- Today's key economic events and data releases, with UK times.
Focus on markets overall. Mention individual companies only if they are market-moving or particularly noteworthy (e.g. a mega-cap result that drives an index).

Be very selective: leave out anything a busy investor would not miss. Never pad a section; drop it if nothing matters.
Hard limit: 500 words in total.

Use web search to find overnight and early-morning moves (Asian session, US close, European futures), news since yesterday's close and today's economic calendar. Prefer reputable sources (central banks, statistics offices, Reuters, Bloomberg, FT, WSJ, BBC, CNBC). Our own closing data and headlines are supplied below; use them, and do not contradict them unless a search shows newer figures. Quote levels and changes with units (bp for yields, % for prices). If you cannot confirm a number, leave it out rather than guess.

Format exactly as markdown with these headings, in this order, omitting any with nothing important:
## The big picture
(two or three sentences)
## Rates
## Equities
## FX
## Commodities
## Macro & politics
## Today (UK times)
Under each heading use short "- " bullets; bold at most a few key phrases with **. No tables, no links, no preamble or sign-off.`;

/** London calendar date and hour for a timestamp. */
export function londonClock(d = new Date()): { date: string; hour: number; weekday: number } {
  const parts = Object.fromEntries(
    new Intl.DateTimeFormat("en-GB", { timeZone: "Europe/London", year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", hourCycle: "h23", weekday: "short" })
      .formatToParts(d)
      .map((p) => [p.type, p.value]),
  );
  const weekday = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].indexOf(parts.weekday);
  return { date: `${parts.year}-${parts.month}-${parts.day}`, hour: Number(parts.hour), weekday };
}

export const wordCount = (s: string) => s.replace(/[#*\-]/g, " ").split(/\s+/).filter(Boolean).length;

export type MdBlock = { type: "h"; text: string } | { type: "li"; text: string } | { type: "p"; text: string };

/** Parses the small markdown subset the briefing uses. */
export function parseBriefing(md: string): MdBlock[] {
  return md
    .split(/\r?\n/)
    .map((l) => l.trim())
    .filter(Boolean)
    .map((l): MdBlock => {
      if (/^#{1,4}\s/.test(l)) return { type: "h", text: l.replace(/^#+\s*/, "") };
      if (/^[-*•]\s/.test(l)) return { type: "li", text: l.replace(/^[-*•]\s*/, "") };
      return { type: "p", text: l };
    });
}

/** Splits "**bold**" runs: [{text, bold}]. */
export function boldRuns(text: string): { text: string; bold: boolean }[] {
  return text
    .split(/(\*\*[^*]+\*\*)/)
    .filter(Boolean)
    .map((t) => (t.startsWith("**") && t.endsWith("**") ? { text: t.slice(2, -2), bold: true } : { text: t, bold: false }));
}
